const fake = document.querySelector("#place-order");
fake.tabIndex = 0; // join the tab order
fake.addEventListener("keydown", (event) => {
  if (event.key === "Enter") fake.click();
  if (event.key === " ") event.preventDefault(); // don't scroll
});
fake.addEventListener("keyup", (event) => {
  if (event.key === " ") fake.click(); // like a native button
});
